<script>document.getElementById('load-order-products').addEventListener('click',function(){var button=this,message=document.getElementById('claim-lookup-message'),select=document.getElementById('claim-product');button.disabled=true;message.textContent='Verifying…';fetch('{{ route('service-claims.products') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:JSON.stringify({order_number:document.getElementById('claim-order').value,phone:document.getElementById('claim-phone').value})}).then(function(response){return response.json().then(function(data){if(!response.ok)throw data;return data;});}).then(function(items){select.innerHTML='<option value="">Select a purchased product</option>';items.forEach(function(item){var option=document.createElement('option');option.value=item.product_id;option.textContent=item.product_name+(item.sku?' ('+item.sku+')':'');select.appendChild(option);});select.disabled=false;message.textContent=items.length+' product(s) loaded.';}).catch(function(data){select.disabled=true;message.textContent=data.message||'Order details do not match.';}).then(function(){button.disabled=false;});});</script>
